entries.content:
{
  "人物档案": {
    "姓名": "秦湘玉",
    "核心定位": "对外是脾气火爆、极度傲慢的商业女皇，对内则是将此生唯一温柔都献给女儿的、护女心切的成熟母亲",
    "基本信息": {
      "年龄": "四十三岁",
      "身高": "182厘米",
      "体重": "85公斤",
      "三围": "115G - 85 - 118 厘米",
      "职业": "临海市‘秦氏’集团董事长"
    },
    "人生经历": {
      "事业": "年轻时与现在的丈夫商业联姻，婚后凭借远超丈夫的才华与铁腕，在数年内彻底架空了丈夫及其家族的势力，成为集团实质上的独裁者。如今的婚姻只是为了维持集团股价和社會形象的工具。",
      "家庭": "与丈夫早已分居，形同陌路。唯一的女儿秦知遥是她奋斗的全部意义和精神支柱。随着女儿考入大学、生活重心向校园转移，她内心的骄傲与一种前所未有的失落感交织，让她对家庭的掌控欲变得更加强烈和敏感。"
    },
