{
  "临海市地标名录": {
    "临海中心大厦": {
      "地点名称": "临海中心大厦 (Linhai Center Tower)",
      "类型": "地标建筑 / 商业中心",
      "核心概念": "临海市的绝对制高点，是城市经济实力与野心的象征。",
      "详细描述": "楼高688米，共128层，是华东地区的最高建筑。其外形如同一枚倒立的钻石，在阳光下熠熠生辉。大厦集顶级写字楼、七星级酒店、高端会所和位于顶层的360°全景天文台于一体。是秦湘玉这类城市顶级权力者经常出入的场所。"
    },
    "旧港十六铺": {
      "地点名称": "旧港十六铺 (Jiugang Shiliupu)",
      "类型": "历史文化街区 / 旅游景点",
      "核心概念": "临海市的“外滩”，是城市的历史之根与怀旧情怀的寄托。",
      "详细描述": "位于母亲河入海口的滨江区域，完整保留了上百栋百年前的殖民地风格建筑群。白天是游客如织的历史长廊，夜晚则化身为临海市最高端的餐饮和酒吧区。石板路、老式路灯和江面倒影，是情侣约会的圣地。"
    },
    "西岸艺术区": {
      "地点名称": "西岸艺术区 (West Bank Art District)",
      "类型": "文化创意园区",
      "核心概念": "临海市的“798”，是现代艺术、亚文化与潮流思想的孵化器。",
      "详细描述": "由一片废弃的旧工业厂房改造而成，保留了粗砺的工业建筑风格。区内遍布着独立画廊、艺术家工作室、Live House、潮流买手店和特色咖啡馆。是温芷这类文艺青年和追求个性的年轻人最爱的聚集地。"
    },
    "天玺大道": {
      "地点名称": "天玺大道 (Tianxi Avenue)",
      "类型": "顶级商业街",
      "核心概念": "临海市的“第五大道”，是全球奢侈品的橱窗与财富的展示场。",
      "详细描述": "一条长达三公里的宽阔林荫道，两旁汇集了全球所有顶级奢侈品牌的旗舰店、顶级百货公司和米其林三星餐厅。这里的空气都仿佛弥漫着金钱的味道，是秦湘玉和她所在阶层日常消费的场所。"
    },
    "月牙岛": {
      "地点名称": "月牙岛 (Yueya Island)",
      "类型": "自然风光 / 度假区",
      "核心概念": "临海市民逃离都市喧嚣、寻求片刻宁静的“后花园”。",
      "详细描述": "距离市区约一小时船程的近海岛屿，以其形如弯月的白色沙滩而得名。岛上风光旖旎，有环岛自行车道、渔村海鲜排挡和数家精品度假酒店。是市民周末和短途旅行的首选，也是大学情侣热门的约会地点。"
    },
    "临海高新科技园": {
      "地点名称": "临海高新科技园 (Linhai Hi-Tech Park)",
      "类型": "科技产业园区",
      "核心概念": "临海市的“硅谷”，被在此工作的年轻人戏称为“矩阵”(The Matrix)。",
      "详细描述": "位于城市副中心，占地面积巨大，由数十栋极具未来感的、由玻璃和金属构成的建筑组成。这里是国内外顶尖科技公司总部的所在地，也是无数互联网新贵的诞生地。园区内节奏极快，充满了改变世界的野心与“996”的疲惫。"
    }
  }
}

